urlset:
{% for page in pages %}

    {{ CANONICAL_BASE }}/{{ '' if page.slug == 'index' else page.url }}

{% endfor %}

    {{ CANONICAL_BASE }}/blog.html

{% for article in articles %}

    {{ CANONICAL_BASE }}/{{ article.url }}
    {{ (article.modified or article.date).strftime('%Y-%m-%d') }}

{% endfor %}
